def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    results = []

    # Build an array to store the segment lengths of offers sorted by position
    # This helps in quickly checking which offers can be accepted for each x

    # For each x from 1 to n, simulate the offer acceptance
    occupied = [0] * (n + 2)  # Mark occupied days

    for x in range(1, n + 1):
        # Reset occupied days for each x
        occupied = [0] * (n + 2)
        total_days = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if all days in [l, r] are unoccupied
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        can_accept = False
                        break

                if can_accept:
                    for day in range(l, r + 1):
                        occupied[day] = 1
                    total_days += length

        results.append(str(total_days))

    return '\n'.join(results) + '\n'

