    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, x, y):
        px, py = find(parent, x), find(parent, y)
        if px != py:
            parent[py] = px

    for x in range(1, n + 1):
        occupied_set = set()
