def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    total = sum(a)

    # If total is 0 or 1, we can't find k > 1
    if total <= 1:
        return "-1"

    # Find all divisors of total
    def get_divisors(num):
        divisors = []
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divisors.append(i)
                if i != num // i:
                    divisors.append(num // i)
        return divisors

    # Calculate moves needed for a given k
    # The cost is sum of absolute cumulative remainders across all edges
    def calc_moves(k):
        cost = 0
        cum_rem = 0
        for i in range(n - 1):
            cum_rem += a[i] % k
            cost += abs(cum_rem)
        return cost

    divisors = get_divisors(total)
    best = float('inf')

    for k in divisors:
        if k > 1:
            best = min(best, calc_moves(k))

    return str(best) if best != float('inf') else "-1"

