def solve(n, edges):
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    memo = {}

    def dfs(u, p):
        # subtree[u][s] = max product from subtree rooted at u
        # where the component containing u has size s

        results = {}

        # Initialize: single node component
        results[1] = 1

        for v in adj[u]:
            if v == p:
                continue

            child_results = dfs(v, u)

            new_results = {}

            for size_u, prod_u in results.items():
                for size_v, prod_v in child_results.items():
                    # Option 1: cut edge (u,v) - multiply products
                    new_size = size_u
                    new_prod = prod_u * prod_v
                    if new_size not in new_results or new_prod > new_results[new_size]:
                        new_results[new_size] = new_prod

                    # Option 2: keep edge (u,v) - add sizes
                    new_size = size_u + size_v
                    new_prod = prod_u
                    if new_size not in new_results or new_prod > new_results[new_size]:
                        new_results[new_size] = new_prod

            results = new_results

        return results

    def get_max_from_results(results):
        return max(results.values())

    cache = {}

    def memoized_dfs(u, p):
        key = (u, p)
        if key in cache:
            return cache[key]

        results = {}
        results[1] = 1

        for v in adj[u]:
            if v == p:
                continue

            child_results = memoized_dfs(v, u)

            new_results = {}
            for s1, p1 in results.items():
                for s2, p2 in child_results.items():
                    # Cut edge: multiply
                    key = s1
                    v = p1 * p2
                    if key not in new_results or v > new_results[key]:
                        new_results[key] = v

                    # Keep edge: add size
                    key = s1 + s2
                    v = p1
                    if key not in new_results or v > new_results[key]:
                        new_results[key] = v

            results = new_results

        cache[(u, p)] = results
        return results

    res = memoized_dfs(1, 0)
    return max(res.values())

