import sys


def is_gp(arr):
    """Check if the given array is a geometric progression."""
    n = len(arr)
    if n <= 2:
        return True

    # All zeros case
    if arr.count(0) == n:
        return True

    # If first is zero, all must be zero
    if arr[0] == 0:
        for x in arr[1:]:
            if x != 0:
                return False
        return True

    # Use cross-multiplication to avoid floating point issues
    # For GP: arr[i-1]/arr[i-2] = arr[i]/arr[i-1]
    # Cross-multiplied: arr[i] * arr[i-2] = arr[i-1]^2
    for i in range(2, n):
        if arr[i] * arr[i-2] != arr[i-1] ** 2:
            return False

    return True


def can_make_gp_by_deletion(arr):
    """Try removing each element and check if remaining forms GP."""
    n = len(arr)
    for i in range(n):
        # Create new array without element at index i
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return True
    return False


def solution(input_str):
    """Solve the geometric progression problem."""
    data = input_str.strip().split()
    if not data:
        return "2\n"

    n = int(data[0])
    arr = [int(x) for x in data[1:]]

    # Take exactly n elements (in case there's extra whitespace)
    arr = arr[:n]

    if is_gp(arr):
        return "0\n"
    elif can_make_gp_by_deletion(arr):
        return "1\n"
    else:
        return "2\n"


