    transformers = []
    for i in range(1, K + 1):
        line = lines[i].split()
        x, y, d, t, e = int(line[0]), int(line[1]), int(line[2]), int(line[3]), int(line[4])
        transformers.append((x, y, d, t, e))

    # Precompute which transformer appears at which (position, arrival_time)
    # transformers[(r, c, t)] = list of transformer indices
    # arrival_time = r + c

    pos_time_map = {}  # (r, c, time) -> energy cost

    for idx, (x, y, d, t, e) in enumerate(transformers):
        # Only consider if transformer starts at or before max time (N+M-2)
        if t <= N + M - 2:
            # Phase 0: starts at (x, y) at absolute time t
            # Phase 1: (x+d, y-d) at absolute time t+1
            # Phase 2: (x+d, y) at absolute time t+2
            # Phase 3: (x, y+d) at absolute time t+3
            for phase in range(4):
                r, c = x, y
                if phase == 1:
                    r += d
                    c -= d
                elif phase == 2:
                    r += d
                elif phase == 3:
                    c += d

                # Check if this position is actually at time (r+c)
                abs_time = r + c
                if abs_time == t + phase:
                    if (r, c) in pos_time_map:
                        pos_time_map[(r, c)].append(e)
                    else:
                        pos_time_map[(r, c)] = [e]

    # Group energy costs by (r, c)
    energy_by_pos = {}
    for (r, c), costs in pos_time_map.items():
        energy_by_pos[(r, c)] = sum(costs)

    # Transform achievable points to avoid duplicates
    reachable = {}  # (r, c) -> min energy to reach here

    # DFS/DP from (0,0) at time 0
    # We can reach (r, c) at exactly time r+c

    q = [(0, 0, 0)]  # (r, c, energy)
    visited = set()
    visited.add((0, 0))
    reachable[(0, 0)] = 0

    # BFS/dynamic programming approach
    for r in range(N):
        for c in range(M):
            if (r, c) in reachable:
                current_energy = reachable[(r, c)]

                # Add cost if there are transformers here
                if (r, c) in energy_by_pos:
                    current_energy += energy_by_pos[(r, c)]

                # Try moving down
                if r + 1 < N:
                    new_pos = (r + 1, c)
                    if new_pos not in reachable or current_energy < reachable[new_pos]:
                        reachable[new_pos] = current_energy

                # Try moving right
                if c + 1 < M:
                    new_pos = (r, c + 1)
                    if new_pos not in reachable or current_energy < reachable[new_pos]:
                        reachable[new_pos] = current_energy

    result = reachable.get((N - 1, M - 1), float('inf'))
    return str(result) + '\n'


