    directions = [(1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)]

    # Handle very large k by considering the pattern
    # With deleted squares only in |x|,|y| <= 10, for large k most positions are reachable
    # We'll run BFS but need to optimize for very large k
    LIMIT = 2500  # Adjust as needed based on problem constraints

