            x, y, moves = queue.popleft()
            if moves >= k:
                continue

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                # Optimization: skip positions very far from origin when k is large
                if (nx, ny) not in visited:
                    if abs(nx) > 2 * k or abs(ny) > 2 * k:
                        continue
                    visited.add((nx, ny))
                    queue.append((nx, ny, moves + 1))
    else:
        # For very large k, run BFS to find when pattern stabilizes
        # For this problem, we use the bounded region approach
        # The deleted squares are within |x| <= 10, |y| <= 10
        # For large k, most positions become reachable except deleted ones
        limit_x = 100
        limit_y = 100

        while queue:
            x, y, moves = queue.popleft()
            if moves >= k:
