    def digit_length(n):
        """Return number of digits in n."""
        if n == 0:
            return 1
        return len(str(n))

    def length_of_block(n):
        """Calculate total length (in digits) of block 1 to n."""
        if n <= 9:
            # All numbers from 1 to n have 1 digit each
            return n
        else:
            # Numbers 1-9 have 1 digit each (9 numbers)
            length = 9
            # Numbers 10-n have 2 digits each
            if n < 100:
                length += (n - 9) * 2
            elif n < 1000:
                length += 90 * 2
                length += (n - 99) * 3
            elif n < 10000:
                length += 900 * 3
                length += (n - 999) * 4
            elif n < 100000:
                length += 9000 * 4
                length += (n - 9999) * 5
            elif n < 1000000:
                length += 90000 * 5
                length += (n - 99999) * 6
            elif n < 10000000:
                length += 900000 * 6
                length += (n - 999999) * 7
            else:
                length += 9000000 * 7
                length += (n - 9999999) * 8
            return length

    def find_digit_in_block(block_num, position):
        """Find the digit at given 1-indexed position within block 1 to block_num."""
        digit = position
        num = 1
        while True:
            d = digit_length(num)
            if digit <= d:
                return str(num)[digit - 1]
            digit -= d
            num += 1

