            right_val = solve(children[node][1])

            lc = count_leaves(node)

            # For subtrees with 2 leaves, current player chooses
            # Number of operations in subtree = lc - 2
            # Max if odd number of operations, min if even
            ops = lc - 2

            if ops % 2 == 1:
                return max(left_val, right_val)
            else:
                return min(left_val, right_val)

        result = solve(0)
        results.append(str(result))

    return '\n'.join(results)


