    reachable = {0}

    for step, (t, x, y) in enumerate(operations, 1):
        new_reachable = set()

        if t == 1:
            # Type 1: k := ceil(k + x)
            # ceil(k + x) = k + ceil(x) since k is integer
            ceil_x = int(math.ceil(x))
            for v in sorted(reachable):
                if v > m:
                    continue
                # Apply operation a times (0 to y times)
                for a in range(y + 1):
                    new_v = v + a * ceil_x
                    if new_v <= m:
                        new_reachable.add(new_v)
        else:
            # Type 2: k := ceil(k * x)
            # Need to compute iteratively since each step applies ceiling
            for v in sorted(reachable):
                if v > m:
                    continue
                current = v
                for a in range(y + 1):
                    if current > m:
                        break
                    new_reachable.add(current)
                    if a < y:
                        current = math.ceil(current * x)

        # Update ans with new reachable values (only if first time reached)
        for v in sorted(new_reachable):
            if v > 0 and ans[v] == -1:
                ans[v] = step

        reachable = new_reachable

    return ' '.join(str(ans[i]) for i in range(1, m + 1))

def solution(input_str):
    l, r = map(int, input_str.strip().split())

    # Clamp to problem limits
    if r > 3 * 10**8:
        r = 3 * 10**8
    l = max(1, l)

    if l > r:
        return "0\n"

    # Generate base primes up to sqrt(r) using basic sieve
    limit = int(r**0.5) + 1

    sieve_size = limit + 1
    is_base_prime = [True] * sieve_size
    is_base_prime[0] = is_base_prime[1] = False

    for i in range(2, int(sieve_size**0.5) + 1):
        if is_base_prime[i]:
            for j in range(i*i, sieve_size, i):
                is_base_prime[j] = False

    base_primes = [i for i in range(2, limit + 1) if is_base_prime[i]]

    # Segmented sieve for range [l, r]
    block_size = max(10000, 5000000)  # Reasonable block size
    start = l

    count = 0

    while start <= r:
        end = min(start + block_size, r + 1)
        block_len = end - start

        # Initialize block - all assumed prime initially
        is_prime_block = [True] * block_len

        # Handle 2 specially
        if 2 in base_primes:
            # Mark even numbers in block as not prime
            for i in range(block_len):
                num = start + i
                if num > 2 and num % 2 == 0:
                    is_prime_block[i] = False

        # Use base primes to mark composites
        for p in base_primes:
            if p * p < start:
                continue

            # Find first multiple of p >= start (starting from p*p for sieve correctness)
            first_mult = ((start + p - 1) // p) * p
            if first_mult < p * p:
                first_mult = p * p

            if first_mult >= start:
                # Mark multiples of p in the block
                idx = first_mult - start
                while idx < block_len:
                    is_prime_block[idx] = False
                    idx += p

        # Count primes that are 2 or ≡ 1 (mod 4)
        for i in range(block_len):
            num = start + i
            if is_prime_block[i]:
                if num == 2 or num % 4 == 1:
                    count += 1

        start = end

    return f"{count}\n"

