import sys
from functools import lru_cache

MOD = 10**9 + 7

def count_digits(n):
    if n == 0:
        return 1
    return len(str(abs(n)))

def power_of_10[digits, memo]:
    if digits in memo:
        return memo[digits]
    result = 1
    for _ in range(digits):
        result = (result * 10) % MOD
    memo[digits] = result
    return result

def prefix_sum(node):
    """Returns (value mod MOD, digit_count) for concatenated prefix"""
    return node

def concat_mod(a, b, mod_digits):
    """Concatenate a and b: a * 10^len(b) + b"""
    factor = power_of_10[mod_digits, {}]
    return (a * factor + b) % MOD

class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        result = self.parse_term()

        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            term = self.parse_term()
            # term concatenation
            val, digits = term
            # If we're just storing, we use prefix_sum
            result_val, result_digits = prefix_sum(result)
            result = (result_val * power_of_10[digits, {}] + val) % MOD

        return result

    def parse_term(self):
        # term ::= number | number '-' number | number '(' expression ')'

        # Parse first number
        num = self.peek_number()
        if num is None:
            return (0, 0)

        l, l_digits = num

        # Check for '-' (range)
        if self.pos < len(self.s) and self.s[self.pos] == '-':
            self.pos += 1
            r = self.peek_number()
            if r is None:
                return (0, 0)
            r_val, r_digits = r

            return self.compute_range(l_val, r_val)

        # Check for '(' (repetition)
        if self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1  # skip '('
            expr = self.parse_expression()

            if self.pos < len(self.s) and self.s[self.pos] == ')':
                self.pos += 1  # skip ')'
            else:
                return (0, 0)

            # repetition: l * expr will be concatenated l times
            expr_val, expr_digits = expr

            return self.compute_repetition(l_val, expr_val, expr_digits)

        # Just a single number
        return (l_val, l_digits)

    def peek_number(self):
        """Parse and peek at a number"""
        # Only parse if we can
        if self.pos >= len(self.s):
            return None

        # Check digit
        if not ('0' <= self.s[self.pos] <= '9'):
            return None

        # Count digits
        start_pos = self.pos
        while self.pos < len(self.s) and '0' <= self.s[self.pos] <= '9':
            self.pos += 1

        num_str = self.s[start_pos:self.pos]
        return (int(num_str), len(num_str))

    def compute_range(self, l, r):
        """Compute concatenation of l, l+1, ..., r"""
        if l > r:
            return (0, 0)

        if l == r:
            return (l % MOD, count_digits(l))

        # Iterative: concatenate l, then l+1, ..., r
        result_val = 0
        result_digits = 0

        for i in range(l, r + 1):
            new_digits = count_digits(i)
            result_val = (result_val * power_of_10[new_digits, {}] + i) % MOD
            result_digits += new_digits

        return (result_val, result_digits)

    def compute_repetition(self, count, expr_val, expr_digits):
        """Compute expr repeated 'count' times"""
        if count <= 0:
            return (0, 0)

        # Binary exponentiation style for efficiency
        result_val = 0
        result_digits = 0

        while count > 0:
            if count % 2 == 1:
                result_val = (result_val * power_of_10[expr_digits, {}] + expr_val) % MOD
                result_digits += expr_digits
            count //= 2
            expr_val = (expr_val * power_of_10[expr_digits, {}] + expr_val) % MOD

        return (result_val, result_digits)

def solution(expression):
    parser = Parser(expression)
    result = parser.parse()
    return str(result)

