def solution(input_str):
    import sys

    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    n, r = map(int, lines[0].split())

    # Generate all integer points within distance r from origin
    points = set()
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.add((x, y))

    points = list(points)

    # Function to calculate sum of squared distances between all pairs
    def calc_distance(points_list):
        total = 0
        count = 0
        for i in range(len(points_list)):
            for j in range(i+1, len(points_list)):
                dx = points_list[i][0] - points_list[j][0]
                dy = points_list[i][1] - points_list[j][1]
                total += dx*dx + dy*dy
                count += 1
        return total

    # For small n, we can try various strategies
    if n == 2:
        best_score = 0
        best_arrangement = [(0, 0)] * 2
        for p1 in points:
            for p2 in points:
                score = calc_distance([p1, p2])
                if score > best_score:
                    best_score = score
                    best_arrangement = [p1, p2]
        return f"{best_score}\n" + "\n".join([f"{p[0]} {p[1]}" for p in best_arrangement])

    # Strategy 1: Try symmetric points around origin
    best_score = 0
    best_arrangement = [(0, 0)] * n

    # Generate all combinations with replacement from a subset of important points
    # Important points are on the boundary: x^2 + y^2 = r^2 or close to it
    boundary_points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            d2 = x*x + y*y
            if d2 <= r*r and (r*r - d2 <= 3):  # Within 3 units squared from boundary
                boundary_points.append((x, y))

    boundary_points = list(set(boundary_points))

    # For very small n, enumerate more combinations
    if n <= 6:
        for combo in __import__('itertools').combinations_with_replacement(boundary_points, n):
            score = calc_distance(list(combo))
            if score > best_score:
                best_score = score
                best_arrangement = list(combo)

    if best_score == 0:
        # If all boundary points give 0, try all valid points
        for combo in __import__('itertools').product(points, repeat=n):
            score = calc_distance(list(combo))
            if score > best_score:
                best_score = score
                best_arrangement = list(combo)

    return f"{best_score}\n" + "\n".join([f"{p[0]} {p[1]}" for p in best_arrangement])

