            self.size *= 2
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)
        self.period_sum = [0] * (2 * self.size)
        for i in range(n):
            self.tree[self.size + i] = arr[i] * (i + 1)
        for i in range(n, self.size):
