            self.sum_periodic = sum(pos * 1 for pos in range(n)) if n else 0
        self.build(0, self.size - 1)

    def build(self, node, l, r):
        if l == r:
            return
        mid = (l + r) // 2
        self.build(2*node+1, l, mid)
        self.build(2*node+2, mid+1, r)
        self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

    def update(self, node, l, r, ql, qr, val):
        if l > qr or r < ql or val == 0:
            return
        if l >= ql and r <= qr:
            self.lazy[node] += val
            self.tree[node] += val * (r - l + 1)
            pos_sum = sum(l + i for i in range(r - l + 1))
            self.tree[node] += pos_sum * val
            return
        mid = (l + r) // 2
        self.push(node, mid - l + 1, r - mid)
        self.update(2*node+1, l, mid, ql, qr, val)
        self.update(2*node+2, mid+1, r, ql, qr, val)
        self.tree[node] = self.tree[2*node+1] + self.tree[2*node+2]

    def push(self, node, freq1, freq2):
        if self.lazy[node] == 0:
            return
        val = self.lazy[node]
        for i in range(freq1):
            self.tree[2*node+1] += val
        for i in range(freq2):
            self.tree[2*node+2] += val
        self.lazy[2*node+1] += val
        self.lazy[2*node+2] += val
        self.lazy[node] = 0

