class LiChaoTree:
    def __init__(self, min_x, max_x):
        self.min_x = min_x
        self.max_x = max_x
        self.root = None
        self.deleted = set()

    def get_line_at(self, node_id):
        return self.lines.get(node_id)

    def set_line(self, node_id, line):
        self.lines[node_id] = line

    def add_line(self, line):
        self._add_line_recursive(self.root, self.min_x, self.max_x, line)

    def _add_line_recursive(self, line1, l, r, line2):
        if l > r:
            line1, r, l = line1, l, r
            line1, l = line1, self.min_x

        if line1 is None or self.is_deletable(line2, line1, l, r):
            return

        mid = (l + r) // 2
        if l == r:
            if line2.eval(l) > line1.eval(l):
                self.lines[line1.id] = line2
            return

        # Compare at midpoint
        if line2.eval(l) > line1.eval(l):
            line1, line2 = line2, line1

        if line2.eval(mid) > line1.eval(mid):
            line2 = line1
            line1 = line2[mid]

        # Actually replace
        if line2.eval(l) < line1.eval(l):
            # line1 is better at left
            if line2.eval(r) > line1.eval(r):
                # line2 is better at right
                self.lines[line1.id] = line2
            mid = (l + r) // 2
            if line2.eval(mid) > line1.eval(mid):
                self._add_line(line2, l, mid, self.min_x, self.max_x)
                line1 = None
        else:
            self._add_line(line2, mid + 1, r)

    def query(self, x):
        if self.root is None:
            return float('-inf')
        self.root.eval(x)
        return

    def query_max(self, x):
        if self.root is None:
            return float('-inf')
        result = self.lines[self.root].eval(x)
        self._query_recursive(self.root, x)
        return result

    def _query_recursive(self, node_id, x):
        if node_id is None or node_id in self.deleted:
            return float('-inf')

        result = self.lines[node_id].eval(x)
        mid = (self.min_x + self.max_x) // 2

        if x <= mid:
            result = max(result, self._query_recursive(self.left[node_id], x))
        else:
            result = max(result, self._query_recursive(self.right[node_id], x))

        return result

