def solution(input_str: str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return ""

    n, m = map(int, lines[0].split())
    d = list(map(int, lines[1].split()))
    h = list(map(int, lines[2].split()))

    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + d[i]

    def clockwise_dist(x, y):
        if x == y:
            return 0
        if x < y:
            return prefix[y] - prefix[x]
        else:
            return prefix[n] - prefix[x] + prefix[y]

    total_dist = prefix[n]

    results = []
    for i in range(m):
        a, b = map(int, lines[3 + i].split())

        blocked = set()
        if a <= b:
            blocked = set(range(a, b + 1))
        else:
            blocked = set(range(a, n + 1)) | set(range(1, b + 1))

        available = [t for t in range(1, n + 1) if t not in blocked]

        if len(available) < 2:
            results.append("0")
            continue

        best = 0
        for x in available:
            for y in available:
                if x == y:
                    continue
                # Query once per unordered pair
                p1, p2 = min(x, y), max(x, y)

                cw = clockwise_dist(p1, p2)
                ccw = total_dist - cw

                # Check if clockwise path goes through blocked range
                blocked_mid = False
                if a <= b:  # blocked is [a,b]
                    if p1 <= p2:
                        blocked_mid = any(a <= t <= b for t in range(p1, p2 + 1))
                else:  # blocked wraps [a,n] and [1,b]
                    blocked_mid = True  # Both forward directions hit blocked since it wraps

                if blocked_mid:
                    dist = ccw
                else:
                    dist = cw

                energy = 2 * (h[p1 - 1] + h[p2 - 1]) + dist
                best = max(best, energy)

        results.append(str(best))

    return '\n'.join(results)

