        # Build edges of derived tree after removing 'removed_v'
        derived_edges = []

        # In complete tree:
        # - Parent of 'removed' is removed_v // 2
        # - Children of 'removed' are 2*removed_v and 2*removed_v+1 (if within bounds)
        parent = removed_v // 2
        direct_children = []
        if removed_v * 2 <= total_complete_vertices:
            direct_children.append(removed_v * 2)
        if removed_v * 2 + 1 <= total_complete_vertices:
            direct_children.append(removed_v * 2 + 1)

        # Generate edges for derived tree (reindexing needed!)
        # Actually the vertex numbers in input are 1 to 2^n - 2

        # Let's use a different approach: label vertices 1 to 2^n-1 in complete tree
        # and see which removal gives matching structure

        for v in range(1, total_complete_vertices + 1):
            if v == removed_v:
                continue  # Skip the removed vertex itself
            if v == parent:
                # Parent of 'removed_v' now connects directly to 'removed_v's children
                for child in direct_children:
                    derived_edges.append((min(parent, child), max(parent, child)))
            elif v * 2 <= total_complete_vertices:
