                    derived_edges.append((v, v * 2 + 1))

        if set(derived_edges) == input_edges:
            results.append(removed_v)

    if not results:
        return '0\n'

    results.sort()
    return str(len(results)) + '\n' + ' '.join(map(str, results)) + '\n'

