            if bal < 0:
                return False
            next_bal = bal + (1 if grid[r][c] == '(' else -1)
            if r < n - 1:
                if check(r + 1, c, next_bal):
                    return True
            if c < m - 1:
                if check(r, c + 1, next_bal):
                    return True
            return False
        return check(0, 0, 0)

    def dfs(idx, grid_copy):
        if idx == n * m:
            if validate(grid_copy):
                result = '\n'.join(''.join(grid_copy[i][j] for j in range(m)) for i in range(n))
                valid_solutions.append(result)
