def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    k = int(lines[0])
    fortune = list(map(int, lines[1].split()))
    q = int(lines[2])

    n_cases = []
    idx = 3
    for i in range(q):
        if idx < len(lines):
            n_cases.append(int(lines[idx]))
            idx += 1

    from functools import lru_cache

    INF = float('inf')
    results = []

    for n in n_cases:
        @lru_cache(maxsize=None)
        def dp(pos, s):
            if s == 0:
                return 0

            if pos >= 20:
                return -INF

            f = fortune[pos] if pos < len(fortune) else fortune[pos % len(fortune)]
            max_sum = 9 * k

            res = -INF
            max_val = 10 ** pos

            for digit_sum in range(min(s // max_val + 2, max_sum + 1)):
                val = digit_sum * max_val
                if val > s:
                    break
                sub = dp(pos + 1, s - val)
                if sub != -INF and sub >= 0:
                    res = max(res, digit_sum * f + sub)

            return res

        ans = dp(0, n)
        if ans == -INF or ans < 0:
            ans = 0
        results.append(str(ans))

    return '\n'.join(results)

from functools import lru_cache

def solution(input_str):
    n = int(input_str.strip())
    MOD = 10**9 + 7

    # Build trie with valid bracket sequences
    trie = {}

    def insert(s):
        node = trie
        for c in s:
            if c not in node:
                node[c] = {}
            node = node[c]
        node['#'] = True

    # Generate all valid bracket sequences and insert into trie
    def generate(current):
        if len(current) == 2 * n:
            insert(current)
            return

        balance = current.count('(') - current.count(')')
        open_count = current.count('(')
        close_count = current.count(')')

        if open_count < n:
            generate(current + '(')
        if close_count < open_count:
            generate(current + ')')

    generate("")

    # Tree DP for maximum matching
    @lru_cache(maxsize=None)
    def dp(balance, remaining):
        if remaining == 0:
            return 0, 0  # Terminal state - leaf node

        c1_list = []

        # Can add '(' if open_count < n (balance + remaining // 2 < n)
        if balance < remaining - (balance + (2 * remaining - balance - 1)):
            c1_list.append(dp(balance + 1, remaining - 1))

        # Can add ')' if balance > 0
        if balance > 0:
            c1_list.append(dp(balance - 1, remaining - 1))

        if not c1_list:
            return 0, 0

        sum_dp1 = sum(c[1] for c in c1_list)
        max_dp0 = max(c[0] for c in c1_list)

        # dp1: node is matched with parent, so we sum children's dp0
        dp1 = sum(c[0] for c in c1_list)

        # dp0: node not matched with parent, so take max by matching with one child
        dp0 = 1 + sum_dp1 + max_dp0

        return (dp0 % MOD, dp1 % MOD)

    # For root, we return dp0 (matched with no parent/source)
    result, _ = dp(0, 2 * n)
    return str(result % MOD)


