from functools import lru_cache

MOD = 10**9 + 7

def solution(x_str):
    digits = [int(c) for c in x_str]
    n = len(digits)

    @lru_cache(maxsize=None)
    def dp(idx, tight, counts):
        if idx == n:
            # All non-zero digits sorted and form the S(n) value
            result = 0
            for d in range(1, 10):
                for _ in range(counts[d]):
                    result = (result * 10 + d) % MOD
            return result

        res = 0
        limit = digits[idx] if tight else 9

        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_counts = [c for c in counts]
            new_counts[d] += 1
            res = (res + dp(idx + 1, new_tight, tuple(new_counts))) % MOD

        return res

    return dp(0, True, (0,) * 10)

